# Protection: Multi-Layer Bytecode XOR Cipher Encryption

import sys, marshal, zlib, base64

_K = b"RUPESH_MAHATO_UNIFIED_PROTECTED_KEY_2026_NEPAL_VIPERP"
_P = ""

def _dx(d, k):
    l = len(k)
    return bytes([b ^ k[i % l] for i, b in enumerate(d)])

try:
    _raw = base64.b64decode(_P)
    _dec = _dx(_raw, _K)
    _decomp = zlib.decompress(_dec)
    _code = marshal.loads(_decomp)
    exec(_code, globals())
except Exception as _e:
    sys.exit(f"❌ Fatal Error: Failed to execute encrypted payload ({_e})")
